DROP POLICY plan_module_access ON public.meeting_requests;
CREATE POLICY plan_module_read ON public.meeting_requests AS RESTRICTIVE FOR SELECT TO authenticated USING (public.is_active_user(auth.uid()));
CREATE POLICY plan_module_create ON public.meeting_requests AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (public.has_module_access(auth.uid(),'can_create_gente_em_acao'));
CREATE POLICY plan_module_respond ON public.meeting_requests AS RESTRICTIVE FOR UPDATE TO authenticated USING (public.is_active_user(auth.uid())) WITH CHECK (public.is_active_user(auth.uid()));
CREATE OR REPLACE FUNCTION public.invite_subscriber_premium(_profile_id uuid,_meeting_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.meetings%ROWTYPE; pid uuid; BEGIN IF auth.uid() IS NULL OR NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT * INTO m FROM public.meetings WHERE id=_meeting_id AND event_type='premium_group' AND meeting_date >= (now() AT TIME ZONE 'America/Sao_Paulo')::date; IF m.id IS NULL THEN RAISE EXCEPTION 'Encontro Premium indisponível'; END IF; IF NOT public.has_role(auth.uid(),'admin') AND NOT (public.has_role(auth.uid(),'facilitador') AND public.is_team_facilitator(auth.uid(),m.team_id)) THEN RAISE EXCEPTION 'forbidden'; END IF; IF NOT public.is_subscriber(_profile_id) OR NOT public.is_showcase_profile(_profile_id) THEN RAISE EXCEPTION 'Selecione um Assinante ativo'; END IF; INSERT INTO public.guest_participations(profile_id,team_id,meeting_id,invited_by,status,metadata) VALUES(_profile_id,m.team_id,m.id,auth.uid(),'invited','{"source":"subscriber_premium_invitation"}'::jsonb) ON CONFLICT DO NOTHING RETURNING id INTO pid; IF pid IS NULL THEN SELECT id INTO pid FROM public.guest_participations WHERE profile_id=_profile_id AND meeting_id=m.id AND status<>'cancelled' LIMIT 1; END IF; RETURN pid; END $$;
REVOKE ALL ON FUNCTION public.invite_subscriber_premium(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.invite_subscriber_premium(uuid,uuid) TO authenticated;
COMMENT ON FUNCTION public.invite_subscriber_premium(uuid,uuid) IS 'Authenticated entry point: active admin or facilitator of meeting group only, subscriber target only; no attendance or account creation.';
CREATE OR REPLACE FUNCTION public.validate_profile_public_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.public_profile_enabled AND NEW.public_profile_enabled IS DISTINCT FROM OLD.public_profile_enabled AND NOT public.has_module_access(NEW.id,'public_profile_enabled') THEN RAISE EXCEPTION 'Publicação exige plano Membro Premium com recurso ativo'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_profile_public_access() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER profile_public_plan BEFORE UPDATE OF public_profile_enabled ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.validate_profile_public_access();
DO $$ DECLARE def text; BEGIN def:=pg_get_functiondef('public.get_public_profile(text)'::regprocedure); def:=replace(def,'p.public_profile_enabled', '(p.public_profile_enabled AND public.has_module_access(p.id, ''public_profile_enabled''))'); EXECUTE def; END $$;
DROP POLICY plan_module_access ON public.activity_feed;
CREATE POLICY plan_feed_read ON public.activity_feed AS RESTRICTIVE FOR SELECT TO authenticated USING (public.has_module_access(auth.uid(),'can_access_feed') OR (user_id=auth.uid() AND activity_type IN ('plan_assigned','meeting_request','meeting_response')));
